package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class HelpFormatter_renderWrappedText_TriageGen0Test {

    private HelpFormatter formatter;
    private StringBuffer sb;

    @Before
    public void setUp() {
        formatter = new HelpFormatter();
        sb = new StringBuffer();
    }

    @Test
    public void testRenderWrappedText_NoWrap() {
        String text = "NoWrapText";
        int width = 20;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("NoWrapText\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_SingleLineWrap() {
        String text = "This is a single line wrap test.";
        int width = 10;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("This is a\n    single\n    line\n    wrap\n    test.\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleLineWrap() {
        String text = "Multiple line wrap test to check indentation.";
        int width = 15;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("Multiple\n    line\n    wrap\n    test\n    to\n    check\n    inden-\n    tation.\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_EmptyString() {
        String text = "";
        int width = 10;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WidthLessThanTextLength() {
        String text = "Short";
        int width = 3;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("Sho\n    rti\n    ng\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NextLineTabStopZero() {
        String text = "Test with zero tab stop.";
        int width = 15;
        int nextLineTabStop = 0;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("Test with\nzero tab\nstop.\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WhitespaceOnly() {
        String text = "   Whitespace   ";
        int width = 10;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("Whitespace\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_LeadingWhitespace() {
        String text = "   Leading whitespace.";
        int width = 10;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("Leading\n    white-\n    space.\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_TrailingWhitespace() {
        String text = "Trailing whitespace.   ";
        int width = 10;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("Trailing\n    white-\n    space.\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NewlineInText() {
        String text = "Line1\nLine2";
        int width = 5;
        int nextLineTabStop = 4;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("Line1\n    Line2\n", sb.toString());
    }
}
